// Entirely synthetic. Usable in Node fake-IDB or an isolated Chrome worker.
import {AIPresentationRunner} from '../../core/organizer/ai-presentation.js';
import {DeepSeekOrganizerProvider} from '../../core/organizer/deepseek.js';
import {AI_LIST_FIELDS} from '../../core/organizer/ai-contract.js';
export const longTermNames=['PAIA 产品设计','ChatGPT 会话与上下文管理','会话窗口问题','学习实验','阅读与笔记','园艺观察','旅行准备','健康作息','写作练习','职业选择','家庭沟通','语言学习','研究方法','财务记录','空间设计','时间安排','代码质量','界面体验','数据保护','复盘习惯','音乐欣赏','摄影练习','运动计划','团队协作','工具选择','问题清单','生活记录','项目进度','创作方向','长期目标'];
const op=()=>crypto.randomUUID(),generator={providerId:'fixture',providerVersion:'1',modelVersion:'synthetic-long-term',taskSchemaVersion:1,promptTemplateVersion:1,policyVersion:1};
export async function seedLongTerm(s,{withAI=true,inputCount=500,entryCount=360,topicNames=longTermNames}={}){
 if(!(await s.status()).consented)await s.consent(true);await s.setFilterMode('off');
 const epoch=(await s.status()).epoch;
 for(let base=0;base<inputCount;base+=100)await s.capture({epoch,adapterVersion:'0.3.0',chat:{id:'synthetic-long-term',url:'https://chatgpt.com/c/synthetic-long-term',title:'完全虚构的长期思想记录'},messages:Array.from({length:Math.min(100,inputCount-base)},(_,offset)=>{const i=base+offset,theme=i%topicNames.length;return {sourceMessageId:'long-term-'+i,pageOrder:i+1,originalText:`${topicNames[theme]}：这是第 ${i+1} 条虚构记录。${i%3===0?'我决定先验证一个明确的问题，再逐步补充证据。':i%3===1?'我还不能确定这个选择，暂时保留不同的可能。':'经过新的观察，我修正了最初的假设，但保留当时的思考过程。'} ${theme===1||theme===2?'ChatGPT 上下文与会话窗口应该一起管理，窗口满时整理已有内容并保留问题。':''}`};})});
 const records=await s.run(()=>s.repository.transaction(false,t=>t.all('records'))),byMessage=new Map(records.map(r=>[r.value.sourceMessageId,r]));
 await s.foundationWrite(async t=>{for(let i=0;i<inputCount;i++){const row=byMessage.get('long-term-'+i);row.value.sourceSentAt=new Date(Date.UTC(2025,Math.floor(i/topicNames.length),1+i%26,8,i%60)).toISOString();row.value.timeSource='chatgpt_response_create_time';row.value.timeConfidence='high';await s.saveRecord(t,row.value,await t.get('recordIndex',row.id));}});
 const topics=[],sections=[],entries=[];
 for(let i=0;i<topicNames.length;i++){const topic=await s.createTopic({name:topicNames[i],operationId:op()});topics.push(topic.id);let revision=0;const ids=[];for(const title of ['起点与问题','决定与原则','后续修正']){const section=await s.createSection({topicId:topic.id,expectedTopicRevision:revision,title,operationId:op()});revision=section.topicRevision;ids.push(section.sectionId);}sections.push(ids);}
 for(let i=0;i<entryCount;i++){const record=byMessage.get('long-term-'+i),inputId='block:'+record.id,topicId=topics[i%topicNames.length],evidence=await s.evidenceFor([{inputId,role:'primary',selectedFields:['body']}]),entry=await s.createEntry({actor:'ai',operationId:op(),body:record.value.originalText,title:'',note:'',type:i%3===0?'decision':i%3===1?'idea':'reflection',formation:'explicit',evidence,generator});entries.push(entry.id);const topic=await s.topic(topicId);await s.placeEntry({entryId:entry.id,topicId,sectionId:sections[i%topicNames.length][Math.floor(i/topicNames.length)%3],expectedEntryRevision:entry.revision,expectedTopicRevision:topic.organizationRevision,operationId:op()});}
 for(let i=0;i<20;i++){const e=await s.entry(entries[i]);await s.editLibraryFields({id:e.id,expectedRevision:e.revision,expectedFieldRevisions:e.fieldRevisions,changes:{body:e.body+' 这是用户亲自保留的合成修订。',note:'合成备注：先确认事实，保留问题。',title:i===0?'明确维护的产品原则':e.title},operationId:op()});}
 const removedInput='block:'+byMessage.get('long-term-5').id,b=await s.input(removedInput);await s.editDocument({operationId:op(),documentId:b.documentId,blocks:[{id:b.id,expectedRevision:b.revision,libraryText:b.libraryText,note:b.note,excluded:true}]});
 const deletedSource=byMessage.get('long-term-'+(inputCount-1));await s.permanentDelete(deletedSource.id);await s.drainPurgeCleanup();await s.drainInvalidations();
 const removedEntry=await s.entry(entries[350]);await s.removeEntry({id:removedEntry.id,expectedRevision:removedEntry.revision,operationId:op()});
 const first=await s.topic(topics[0]);await s.editTopic({id:first.id,expectedRevision:first.revision,changes:{pinned:true},operationId:op()});
 let aiRequests=0;if(withAI){const provider=new DeepSeekOrganizerProvider({limits:s.organizerBudget.limits,fetchImpl:async(_url,init)=>{aiRequests++;const r=JSON.parse(JSON.parse(init.body).messages[1].content),content={topicId:r.topicCandidates[0].id,blockSummary:'从明确问题出发，保留证据与后续修正。',currentView:'先确认事实与问题，再根据新观察调整计划。',...Object.fromEntries(AI_LIST_FIELDS.map(k=>[k,[]])),decisions:[{text:'先验证明确的问题。',evidenceEntryIds:r.inputs.map(x=>x.ref)}],openQuestions:[{text:'新的观察是否足以改变当前判断？',evidenceEntryIds:r.inputs.map(x=>x.ref)}],evidenceEntryIds:r.inputs.map(x=>x.ref)};return {ok:true,status:200,headers:{get:()=>null},text:async()=>JSON.stringify({choices:[{message:{content:JSON.stringify(content)}}]})};}}),credentials={acquire:async()=>({status:'ready',handle:'synthetic-only'}),revoke:()=>{}},runner=new AIPresentationRunner(s,{provider,credentials});for(const topicId of topics.slice(0,3))for(let i=0;i<2;i++){const result=await runner.wake({userActionId:op(),topicId});if(result.error)throw new Error(result.error);}const e=await s.entry(entries[0]);await s.editLibraryFields({id:e.id,expectedRevision:e.revision,expectedFieldRevisions:e.fieldRevisions,changes:{note:e.note+' 新的合成思考尚待 AI整理。'},operationId:op()});}
 await s.drainLibraryMaintenance();return {capturedInputs:inputCount,currentSources:inputCount-1,topicIds:topics,sectionIds:sections,entryIds:entries,removedInput,removedEntry:removedEntry.id,tombstoneSourceKey:deletedSource.value.sourceKey,aiRequests};
}
